import { test, expect } from '@playwright/test';

test.describe('User Profile Preferences', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
  });

  test('should toggle dark mode on', async ({ page }) => {
    const darkModeToggle = page.getByRole('checkbox', { name: /dark mode/i });
    await darkModeToggle.check();
    const body = page.locator('body');
    await expect(body).toHaveClass(/dark-mode/);
  });

  test('should toggle dark mode off', async ({ page }) => {
    const darkModeToggle = page.getByRole('checkbox', { name: /dark mode/i });
    await darkModeToggle.uncheck();
    const body = page.locator('body');
    await expect(body).not.toHaveClass(/dark-mode/);
  });
});
